// Armoni pregunta: la IA revisa los movimientos, pregunta lo que no está claro y aprende de lo que le contestan.
// pendientes: las preguntas sin responder · revisar: busca movimientos dudosos y arma preguntas · responder: interpreta la respuesta y aprende
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false, accion: 'error', error: 'token' } }];
const accion = ['pendientes', 'revisar', 'responder', 'saltar', 'olvidar', 'editar', 'completar', 'confirmar', 'corregir', 'autonomia'].includes(b.accion) ? b.accion : 'pendientes';
const sd = $getWorkflowStaticData('global');
sd.preguntas = sd.preguntas || []; sd.memoria = sd.memoria || []; sd.ajustes = sd.ajustes || {}; sd.vistos = sd.vistos || {};
// versión 2: antes se confundían movimientos con códigos parecidos; se empieza de nuevo (lo aprendido se conserva)
if (!sd.v2) { sd.v2 = true; sd.preguntas = []; sd.ajustes = {}; sd.vistos = {}; sd.revisado = ''; }
// lo que la familia ya contó (punto de partida de la memoria)
if (!sd.sembrada) { sd.sembrada = true; sd.memoria.push(
  'Cherry es el carro de la mamá de Carlos: el «SOAT cherry» y su «Pago soat cherry» son un favor (ella devolvió la plata), no son gasto ni ingreso de la familia.',
  '«Pago pc Yepes» fue la venta de un computador y la plata quedó para la familia: es ingreso real.',
  'El «Subsidio Comfandi» es plata que le entra a Emanuel (Ema): es ingreso real de la familia.',
  'Las cajitas de Nu son bolsillos de la misma cuenta: mover plata entre ellas no es gasto ni ingreso. Los rendimientos de las cajitas sí son ingreso.'); }
// la app guarda copia de lo aprendido: si el flujo se reinstaló y solo tiene lo inicial, se recupera
if (Array.isArray(b.memoria) && sd.memoria.length <= 4) { b.memoria.slice(0, 150).forEach(t => { t = String(t || '').trim().slice(0, 240); if (t && !sd.memoria.includes(t)) sd.memoria.push(t); }); }
// la app también guarda copia de los ajustes (favor, traslado, duplicado…): si el flujo se reinstaló y no tiene ninguno, se recuperan
if (b.ajustes && typeof b.ajustes === 'object' && !Object.keys(sd.ajustes).length) {
  Object.keys(b.ajustes).slice(0, 600).forEach(k => { const a = b.ajustes[k]; if (a && ['favor', 'traslado', 'duplicado', 'invertido'].includes(a.clas) && /^[0-9a-f-]{20,40}$/i.test(k)) sd.ajustes[k] = { clas: a.clas, tipo: String(a.tipo || '').slice(0, 10), monto: Number(a.monto) || 0, fecha: String(a.fecha || '').slice(0, 10), cat: String(a.cat || '').slice(0, 30), concepto: String(a.concepto || '').slice(0, 80), nota: String(a.nota || '').slice(0, 120) }; });
}
// olvidar un recuerdo que ya no es cierto
if (accion === 'editar') { const t = String(b.texto || '').trim(), nu = String(b.nuevo || '').trim().slice(0, 240); if (t && nu) { const i = sd.memoria.indexOf(t); if (i >= 0) sd.memoria[i] = nu; else if (!sd.memoria.includes(nu)) sd.memoria.push(nu); } }
if (accion === 'olvidar') { const t = String(b.texto || '').trim(); sd.memoria = sd.memoria.filter(x => x !== t); }
// junio no se va a registrar: se quita ese caso si ya estaba
if (!sd.sinJunio) { sd.sinJunio = true; sd.preguntas = sd.preguntas.filter(q => q.id !== 'caso-jun'); }
// casos abiertos: diferencias entre la cuenta del banco (Nu) y lo registrado en Notion; se resuelven conversando con Armoni
if (!sd.sembrada3) { sd.sembrada3 = true;
  const caso = (id, t) => sd.preguntas.push({ id, tipo: 'caso', estado: 'pendiente', pregunta: t, opciones: [], motivo: 'La cuenta no cuadra con el banco', movs: [], hilo: [{ r: 'a', t }], creada: new Date().toISOString() });
  caso('caso-jul', 'Julio no cuadra con tu cuenta de Nu: en Notion faltan $606.726. La mayor parte es la transferencia a Carlos de $569.032 del 1 de julio, que no está registrada. ¿Fue un ingreso, un gasto, o plata que solo movieron entre ustedes?');
}
// segunda tanda de lo que la familia ya contó
if (!sd.sembrada2) { sd.sembrada2 = true; sd.memoria.push(
  'Carlos y su esposa Aleja («amor») a veces se pasan plata entre ellos: si Carlos le manda plata a Aleja y ella se la devuelve (ej. «Amor devuelve»), son un ida y vuelta que se cancela: no cuenta como ingreso ni como gasto (clasifícalo "favor"). El salario de Aleja, en cambio, sí es ingreso real.'); }
// lo que Armoni decidió solo: la familia lo confirma (✓), lo corrige, o cambia qué tan atrevido es (sin IA; lo maneja «Pendientes»)
sd.decisiones = sd.decisiones || []; sd.patrones = sd.patrones || {}; sd.colaNotion = sd.colaNotion || [];
const decision = String(b.decision || '').trim().slice(0, 40);
if ((accion === 'confirmar' || accion === 'corregir') && !sd.decisiones.some(d => d.id === decision)) return [{ json: { ok: false, accion: 'error', error: 'decision' } }];
const clas = ['real', 'favor', 'traslado', 'duplicado', 'invertido', 'categoria'].includes(b.clas) ? b.clas : '';
const catNueva = String(b.catNueva || '').replace(/[<>{}]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 30);
if (accion === 'corregir' && (!clas || (clas === 'categoria' && !catNueva))) return [{ json: { ok: false, accion: 'error', error: 'clas' } }];
const nivel = ['prudente', 'normal', 'atrevido'].includes(b.nivel) ? b.nivel : '';
if (accion === 'autonomia' && !nivel) return [{ json: { ok: false, accion: 'error', error: 'nivel' } }];
const p = sd.preguntas.find(q => q.id === String(b.id || ''));
if ((accion === 'responder' || accion === 'saltar' || accion === 'completar') && !p) return [{ json: { ok: false, accion: 'error', error: 'pregunta' } }];
const respuesta = String(b.respuesta || '').trim().slice(0, 600);
// «alias»: la familia dijo que un gasto con ese nombre fue en tal lugar (ej. «Hamburguesas noche de juegos» → Hunter): la próxima vez se sugiere ese lugar
if (accion === 'completar' && b.alias && typeof b.alias === 'object') {
  const nT = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\bpareja\b/g, ' ').replace(/\s+/g, ' ').trim();
  const k = nT(b.alias.concepto).slice(0, 60), l = String(b.alias.lugar || '').replace(/[<>{}]/g, ' ').trim().slice(0, 60);
  if (k.length >= 4 && l.length >= 2) { sd.alias = sd.alias || {}; sd.alias[k] = l; const ks = Object.keys(sd.alias); if (ks.length > 300) ks.slice(0, ks.length - 300).forEach(x => delete sd.alias[x]); }
}
if (accion === 'responder' && !respuesta) return [{ json: { ok: false, accion: 'error', error: 'respuesta' } }];
const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
// «revisar» corre como mucho una vez al día (salvo que se pida forzar)
const toca = accion !== 'revisar' || b.forzar || sd.revisado !== hoy;
const dias = Math.min(60, Math.max(1, parseInt(b.dias, 10) || 3));
return [{ json: { ok: true, accion: toca ? accion : 'pendientes', id: p ? p.id : '', respuesta, hoy, dias, decision, clas, catNueva, nivel } }];

// Armoni decidió solo: patrones de lo que acierta / se equivoca (clave = clas + ':' + concepto sin tildes ni números)
const normC = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[0-9]+/g, ' ').replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
const patronDe = (clas, concepto) => clas + ':' + normC(concepto).slice(0, 40);
// lo que Armoni decidió solo, sus ideas y qué tanto decide sin preguntar (últimos 30 días)
const _resumenAuto = (sd) => {
  const desde = new Date(Date.now() - 30 * 864e5).toISOString();
  const D = sd.decisiones || [];
  const recientes = D.filter(d => (d.t || '') >= desde);
  const decididas = recientes.length;
  const preguntadas = (sd.preguntas || []).filter(q => !q.tipo && (q.creada || '') >= desde).length;
  return {
    decisiones: D.slice(-30).reverse(),
    ideas: (sd.ideas || []).slice(0, 6),
    autonomia: { pct: decididas + preguntadas ? Math.round(decididas * 100 / (decididas + preguntadas)) : 0, decididas, preguntadas,
      confirmadas: recientes.filter(d => d.estado === 'confirmada').length, corregidas: recientes.filter(d => d.estado === 'corregida').length, nivel: sd.nivel || 'normal' }
  };
};
// el hilo de la conversación (para el «chat temporal» de cada duda)
const _h = q => (q.hilo && q.hilo.length ? q.hilo : [{ r: 'a', t: q.pregunta }]);
const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
// ---- la familia revisa lo que Armoni decidió solo (sin IA) ----
sd.decisiones = sd.decisiones || []; sd.patrones = sd.patrones || {}; sd.colaNotion = sd.colaNotion || []; sd.ajustes = sd.ajustes || {}; sd.memoria = sd.memoria || [];
const _pat = k => (sd.patrones[k] = sd.patrones[k] || { ok: 0, mal: 0 });
// cambios de signo / categoría que se escriben en Notion (uno por movimiento: el último manda)
const _cola = (id, tipo, categoria) => { sd.colaNotion = sd.colaNotion.filter(x => x.id !== id); sd.colaNotion.push({ id, tipo, categoria }); };
const _ahora = new Date().toISOString();
if (v.accion === 'autonomia' && v.nivel) sd.nivel = v.nivel;
if (v.accion === 'confirmar') { const d = sd.decisiones.find(x => x.id === v.decision); if (d && d.estado === 'auto') { d.estado = 'confirmada'; d.tEstado = _ahora; _pat(patronDe(d.clas, d.concepto)).ok++; } }
if (v.accion === 'corregir') {
  const d = sd.decisiones.find(x => x.id === v.decision);
  if (d) {
    const antes = d.clas, catAntes = d.catNueva || '', nueva = v.clas, cat = v.catNueva || '';
    if (nueva === antes && (nueva !== 'categoria' || cat === catAntes)) {
      // eligieron lo mismo que Armoni ya había decidido: cuenta como «bien»
      if (d.estado === 'auto') { d.estado = 'confirmada'; d.tEstado = _ahora; _pat(patronDe(d.clas, d.concepto)).ok++; }
    } else {
      // Armoni se equivocó en este tipo de caso: la próxima vez pregunta (si una corrección anterior ya lo contó, no se cuenta dos veces)
      if (d.estado !== 'corregida') { const P = _pat(patronDe(antes, d.concepto)); if (d.estado === 'confirmada') P.ok = Math.max(0, P.ok - 1); P.mal++; }
      d.clasAntes = d.clasAntes || antes; d.clas = nueva; if (cat) d.catNueva = cat; else delete d.catNueva;
      d.estado = 'corregida'; d.tEstado = _ahora;
      // cómo cuenta en los totales (el signo al revés se arregla en Notion, no con ajuste, para no voltearlo dos veces)
      if (['favor', 'traslado', 'duplicado'].includes(nueva)) sd.ajustes[d.movId] = { clas: nueva, tipo: d.tipo, monto: d.monto, fecha: d.fecha, cat: d.cat, concepto: d.concepto, nota: 'lo corrigió la familia' };
      else delete sd.ajustes[d.movId];
      // Notion: si cambia la categoría o el signo, o si Armoni ya los había cambiado y hay que devolverlos
      const opuesto = d.tipo === 'Gasto' ? 'Ingreso' : 'Gasto';
      const tipoReal = nueva === 'invertido' ? opuesto : d.tipo;
      if (nueva === 'invertido' || cat || antes === 'invertido' || antes === 'categoria') _cola(d.movId, tipoReal, cat || d.cat);
      // memoria: un hecho corto, y se quitan los que digan otra cosa del mismo concepto (las reglas fijas nunca se tocan)
      const concepto = String(d.concepto || '').trim().slice(0, 80), nc = normC(concepto);
      const unGI = tipoReal === 'Ingreso' ? 'un ingreso' : 'un gasto';
      const expl = { real: unGI + ' real de la familia' + (cat ? ', de la categoría ' + cat : ''), favor: 'un favor: no es gasto ni ingreso de la familia',
        traslado: 'un traslado de plata entre cuentas propias: no es gasto ni ingreso', duplicado: 'un registro repetido (el del ' + (d.fecha || '') + '): no se cuenta dos veces',
        invertido: unGI + ' (estaba registrado al revés)' + (cat ? ', de la categoría ' + cat : ''), categoria: unGI + ' de la categoría ' + cat }[nueva];
      const clave = { real: 'real', favor: 'favor', traslado: 'traslado', invertido: normC(tipoReal), categoria: normC(cat) }[nueva];
      const SIEMBRA = ['Cherry es el carro de la mamá de Carlos', '«Pago pc Yepes»', 'El «Subsidio Comfandi»', 'Las cajitas de Nu', 'Carlos y su esposa Aleja'];
      const fija = x => /espos[oa]s?/i.test(x) || SIEMBRA.some(s => String(x).startsWith(s));
      if (concepto) {
        if (nc.length >= 4 && clave) sd.memoria = sd.memoria.filter(x => fija(x) || !normC(x).includes(nc) || normC(x).includes(clave));
        const hecho = ('«' + concepto + '» es ' + expl + ' (lo corrigió la familia).').slice(0, 240);
        if (!sd.memoria.includes(hecho)) sd.memoria.push(hecho);
        sd.memoria = sd.memoria.length > 150 ? sd.memoria.slice(0, 4).concat(sd.memoria.slice(-146)) : sd.memoria;
      }
    }
  }
}
if (v.accion === 'saltar') { const p = sd.preguntas.find(q => q.id === v.id); if (p) { p.estado = 'saltada'; p.hasta = new Date(Date.now() + (v.dias || 3) * 864e5).toISOString().slice(0, 10); } }
// «completar»: la familia ya dijo dónde fue una salida a comer (se guardó en Restaurantes desde la app); la duda se da por respondida, sin IA
if (v.accion === 'completar') { const p = sd.preguntas.find(q => q.id === v.id); if (p) { p.estado = 'respondida'; p.respuesta = v.respuesta || 'Lugar guardado en Restaurantes'; p.hilo = (p.hilo && p.hilo.length ? p.hilo : [{ r: 'a', t: p.pregunta }]).concat([{ r: 'u', t: p.respuesta }]); } }
const hoy = v.hoy || '';
const pend = (sd.preguntas || []).filter(q => q.estado === 'pendiente' || (q.estado === 'saltada' && (q.hasta || '') <= hoy)).slice(0, 5)
  .map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [], tipo: q.tipo || '', sug: q.sug || null, hilo: _h(q) }));
// todas las dudas sin resolver (también las que dejaron para después) y las últimas respondidas, para la pantalla «Dudas»
const _sd = $getWorkflowStaticData('global');
const _lista = (_sd.preguntas || []);
const abiertas = _lista.filter(q => q.estado === 'pendiente' || q.estado === 'saltada').map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [], saltada: q.estado === 'saltada', creada: q.creada || '', tipo: q.tipo || '', sug: q.sug || null, hilo: _h(q) }));
const hechas = _lista.filter(q => q.estado === 'respondida').slice(-8).reverse().map(q => ({ id: q.id, pregunta: q.pregunta, respuesta: q.respuesta || '', movs: q.movs || [], hilo: _h(q) }));
return [{ json: { abiertas, hechas, saber: _sd.memoria || [], revision: _sd.revision || null, ok: v.ok !== false, error: v.error || null, preguntas: pend, ajustes: sd.ajustes || {}, memoria: (sd.memoria || []).length, ..._resumenAuto(sd) } }];

// referencia corta y única de cada movimiento: el FINAL del código de Notion (el inicio se repite entre páginas)
const ref = (id) => String(id).replace(/-/g, '').slice(-10);
// Lee una propiedad venga como página completa de Notion (properties) o simplificada de n8n (property_xxx)
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : (pr.status ? pr.status.name : null);
    if (tipo === 'relacion') return pr.relation && pr.relation[0] ? pr.relation[0].id : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'relacion') { const r = Array.isArray(v) ? v[0] : v; return r ? (typeof r === 'object' ? r.id : String(r)) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};

const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
sd.revisado = v.hoy;
// regla fija: entre esposos no hay favores
sd.memoria = sd.memoria || [];
const REGLA_PAREJA = 'Carlos y Aleja son esposos con la misma plata: lo que cualquiera de los dos gasta en comida, antojos, papitas, salidas o cosas personales es gasto real de la familia, nunca un favor entre ellos.';
if (!sd.memoria.includes(REGLA_PAREJA)) sd.memoria.unshift(REGLA_PAREJA);
const desde = new Date(Date.now() - 75 * 864e5).toISOString().slice(0, 10);
// lo pagado en efectivo (Monto 0 y valor en «Efectivo») no es un movimiento de la cuenta: no se revisa
// orden de creación (para saber cuál de dos registros iguales es el más nuevo)
const creadoDe = {}, posDe = {};
$input.all().forEach((i, n) => { const x = i.json; if (x && x.id) { creadoDe[x.id] = x.created_time || x.createdTime || ''; posDe[x.id] = n; } });
const diaTR = (f) => new Date(f + 'T12:00:00').getTime();
const base = $input.all().map(i => i.json).filter(x => x && x.id && !((leer(x, 'Efectivo', 'numero') || 0) > 0)).map(x => ({
  id: x.id, fecha: leer(x, 'Fecha', 'fecha') || '', tipo: leer(x, 'Tipo', 'select') || '', cat: leer(x, 'Categoría', 'select') || '',
  monto: leer(x, 'Monto', 'numero') || 0, concepto: leer(x, 'Concepto', 'titulo') || '', notas: leer(x, 'Notas', 'texto') || '', rest: leer(x, 'Restaurante', 'relacion') || ''
}));
const todos = base.filter(m => m.fecha >= desde);
// ===== reglas sin IA (Armoni decide solo lo que está clarísimo) =====
const normC = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[0-9]+/g, ' ').replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
const patronDe = (clas, concepto) => clas + ':' + normC(concepto).slice(0, 40);
let _nDc = 0;
// registra lo que Armoni decidió (y por qué) para que la familia lo confirme o lo corrija con un toque
const decidir = (sd, mov, clas, conf, porque, fuente, catNueva) => {
  sd.decisiones = sd.decisiones || []; sd.ajustes = sd.ajustes || {}; sd.colaNotion = sd.colaNotion || [];
  if (sd.decisiones.some(d => d.movId === mov.id && d.clas === clas)) return null;
  const d = { id: 'dc' + Date.now().toString(36) + (_nDc++), movId: mov.id, concepto: String(mov.concepto || '').slice(0, 80), monto: mov.monto, fecha: mov.fecha, tipo: mov.tipo, cat: mov.cat, clas,
    conf: Math.max(0, Math.min(100, Math.round(conf))), porque: String(porque || '').slice(0, 140), fuente, estado: 'auto', t: new Date().toISOString() };
  if (catNueva) d.catNueva = String(catNueva).slice(0, 30);
  sd.decisiones.push(d);
  if (sd.decisiones.length > 80) sd.decisiones = sd.decisiones.slice(-80);
  if (['favor', 'traslado', 'duplicado', 'invertido'].includes(clas)) sd.ajustes[mov.id] = { clas, tipo: mov.tipo, monto: mov.monto, fecha: mov.fecha, cat: mov.cat, concepto: mov.concepto, nota: d.porque.slice(0, 120) };
  if (clas === 'categoria' || clas === 'invertido') {
    sd.colaNotion = sd.colaNotion.filter(c => c.id !== mov.id);
    sd.colaNotion.push({ id: mov.id, tipo: clas === 'invertido' ? (mov.tipo === 'Gasto' ? 'Ingreso' : 'Gasto') : mov.tipo, categoria: catNueva || mov.cat });
  }
  return d;
};
// (a) duplicados obvios: mismo concepto, mismo monto, mismo tipo y a un día o menos. Se queda el primero y el más nuevo no se cuenta.
// Solo movimientos nuevos (no vistos antes), sin ajuste, sin duda abierta y sin decisión previa. Si la familia ya le corrigió a Armoni
// un «duplicado» de ese concepto (sd.patrones mal >= ok), ya no lo decide solo: lo deja para la IA/la familia.
// (b) el ida y vuelta entre Carlos y Aleja ya lo cubre la memoria: aquí no se toca.
const reglaDup = new Set();
try {
  sd.patrones = sd.patrones || {}; sd.decisiones = sd.decisiones || [];
  const _preg = new Set((sd.preguntas || []).flatMap(q => (q.movs || []).map(m => m.id)));
  const _dec = new Set(sd.decisiones.map(d => d.movId));
  const _orden = (a, b) => a.fecha.localeCompare(b.fecha) || String(creadoDe[a.id] || '').localeCompare(String(creadoDe[b.id] || '')) || (posDe[a.id] - posDe[b.id]);
  const grupos = {};
  todos.forEach(m => { const k = normC(m.concepto); if (k.length < 3 || Math.abs(m.monto) < 2000) return;
    // dos helados, dos almuerzos o dos pasajes iguales en una salida suelen ser uno para cada uno: eso no se marca solo como repetido
    if (/^salidas/.test(normC(m.cat)) || (m.tipo === 'Gasto' && Math.abs(m.monto) < 30000)) return; const g = m.tipo + '|' + k + '|' + Math.round(m.monto); (grupos[g] = grupos[g] || []).push(m); });
  for (const g of Object.values(grupos)) {
    if (g.length < 2) continue;
    g.sort(_orden);
    // cadenas de registros a ±1 día; 3 o más iguales seguidos suelen ser compras reales repetidas (pasajes, cafés): no se deciden
    let cad = [g[0]];
